Here's a C++ program that uses a recursive function to generate the Fibonacci sequence, starting with two given integers as the first two sequence elements:

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <stdexcept>

using namespace std;

int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else if (n == 1) {
        return b;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int first_num, second_num, num_elements;

    cout << "Enter the first two integers: ";
    getline(cin, input);

    istringstream iss(input);
    iss >> first_num >> second_num;

    if (first_num < 0 || second_num < 0) {
        throw runtime_error("Both numbers must be non-negative.");
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> num_elements;

    if (num_elements < 0) {
        throw runtime_error("The number of sequence elements must be non-negative.");
    }

    vector<int> sequence(num_elements);
    sequence[0] = first_num;
    sequence[1] = second_num;

    for (int i = 2; i < num_elements; i++) {
        sequence[i] = fibonacci(i, second_num, first_num + second_num);
    }

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < num_elements; i++) {
        cout << sequence[i] << ", ";
    }
    cout << endl;

    return 0;
}
```

Here's a C++ program that generates the Fibonacci sequence using a recursive function. It prompts the user to input the first two integers and the number of sequence elements to generate. It also includes error handling for invalid inputs.

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <stdexcept>

using namespace std;

int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

void generate_fibonacci_sequence(int num_elements, int a, int b) {
    if (num_elements <= 0) {
        throw runtime_error("Invalid number of elements.");
    }

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < num_elements; i++) {
        cout << fibonacci(i, a, b) << ", ";
    }
    cout << endl;
}

int main() {
    string input;
    int a, b, num_elements;

    cout << "Enter the first two integers: ";
    getline(cin, input);
    istringstream iss(input);
    if (!(iss >> a >> b)) {
        throw runtime_error("Invalid input.");
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> num_elements;

    if (num_elements < 0) {
        throw runtime_error("Invalid number of elements.");
    }

    try {
        generate_fibonacci_sequence(num_elements, a, b);
    } catch (const std::runtime_error& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
