To solve this problem, we can use a combination of string manipulation and regular expressions in Swift. Here's a Swift function that takes in the passage as input and outputs the corrected passage, with all homophones correctly replaced:

```swift
import Foundation

func correctHomophones(in passage: String) -> String {
    let homophones = [
        "there", "their", "they're",
        "to", "too", "two",
        "weather", "whether",
        "no", "know",
        "right", "write",
        "see", "sea",
        "sum", "some",
        "good", "hood",
        "true", "through"
    ]

    let regex = try! NSRegularExpression(pattern: "\\b(\\w+)\\b", options: .caseInsensitive)
    let matches = regex.matches(in: passage, options: [], range: NSRange(location: 0, length: passage.utf16.count))

    for match in matches {
        let word = (passage as NSString).substring(with: match.range)
        if homophones.contains(word) {
            let correctedWord = homophones.first(where: { $0 != word }) ?? word
            passage = (passage as NSString).replacingCharacters(in: match.range, with: correctedWord)
        }
    }

    return passage
}

