        % Get the Morse Code representation of the current character
        morse_code = [morse_code, get_morse_code(phrase{i})];
    end
end

function morse_code = get_morse_code(char)
    % Check if the character is a letter or a digit
    if isletter(char)
        % Get the Morse Code representation of the letter
        morse_code = char_to_morse_code(char);
    elseif isdigit(char)
        % Get the Morse Code representation of the digit
        morse_code = num_to_morse_code(char);
    else
        % Return an empty string if the character is not a letter or a digit
        morse_code = '';
    end
end

function morse_code = char_to_morse_code(char)
    % Get the Morse Code representation of the letter
    switch char
        case 'A'
            morse_code = '.-';
        case 'B'
            morse_code = '-...';
        case 'C'
            morse_code = '-.-.';
        case 'D'
            morse_code = '-..';
