3. Define a custom lookup class to handle the dynamic column names:

```python
from django.db.models import Q
from django.utils.functional import cached_property

class DynamicLookup(Q):
    def __init__(self, column_name, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.column_name = column_name

    @cached_property
    def negated(self):
        return ~self

    def __and__(self, other):
        return self.copy().add(other, Q.AND)

    def __or__(self, other):
        return self.copy().add(other, Q.OR)

    def __xor__(self, other):
        return self.copy().add(other, Q.XOR)

    def __invert__(self):
        return ~self
```

