$std_dev = array_column($filtered_data, 'age');
// Display results
echo "Mean age: " . array_sum($mean) / count($mean) . "<br>";
echo "Standard deviation of age: " . sqrt(array_sum($std_dev) / count($std_dev)) . "<br>";
?>
```
