Here's a MATLAB code that identifies the tense used in a given sentence:

```matlab
function tense = identify_tense(sentence)
    % Split the sentence into words
    words = strsplit(sentence);

    % Check for common indicators of different tenses
    past_simple = {'was', 'were', 'had', 'hadn't', 'did', 'didn't', 'would', 'wouldn't'};
    past_continuous = {'was', 'were', 'had', 'hadn't', 'doing', 'does', 'did', 'didn't', 'being', 'been'};
    present_simple = {'is', 'are', 'has', 'have', 'does', 'do'};
    present_continuous = {'is', 'are', 'has', 'have', 'been', 'being'};
    future_simple = {'will', 'shall', 'may', 'might', 'ought'};
    future_continuous = {'will', 'shall', 'may', 'might', 'be'};
    conditional_present = {'would', 'could', 'should'};
    conditional_past = {'would', 'could', 'should', 'used'};

    % Check each word against the indicators
    for i = 1:numel(words)
        if ismember(words{i}, past_simple) || ismember(words{i}, past_continuous)
            tense = 'Past';
            break;
        elseif ismember(words{i}, present_simple) || ismember(words{i}, present_continuous)
            tense = 'Present';
            break;
        elseif ismember(words{i}, future_simple) || ismember(words{i}, future_continuous)
            tense = 'Future';
            break;
        elseif ismember(words{i}, conditional_present) || ismember(words{i}, conditional_past)
            tense = 'Conditional';
            break;
        end
    end
end

