```

3. Create a function to handle the conversion process:

```javascript
const handleConvert = () => {
  if (!inputTemp) {
    return;
  }

  const temp = parseFloat(inputTemp);
  let convertedTemp = 0;

  if (outputUnit === 'F') {
    convertedTemp = (temp * 9 / 5) + 32;
  } else if (outputUnit === 'K') {
    convertedTemp = temp + 273.15;
  }

  setOutputTemp(convertedTemp.toFixed(2));
};
```

