    )}

Here's a React hook that allows you to convert between different temperature units:

```javascript
import { useState } from 'react';

const useTemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('celsius');

  const handleConvert = (newUnit) => {
    if (newUnit === 'celsius') {
      setTemperature((temperature * 9 / 5) + 32);
      setUnit('fahrenheit');
    } else {
      setTemperature((temperature - 32) * 5 / 9);
      setUnit('celsius');
    }
  };

  return { temperature, unit, handleConvert };
};

export default useTemperatureConverter;
```

To use this hook in your component, import it and call the `useTemperatureConverter` function:

```javascript
import React from 'react';
import useTemperatureConverter from './useTemperatureConverter';

const TemperatureConverter = () => {
  const { temperature, unit, handleConvert } = useTemperatureConverter();

  return (
    <div>
      <h1>Temperature Converter</h1>
      <p>Current temperature: {temperature} {unit}</p>
      <button onClick={() => handleConvert('fahrenheit')}>Convert to Fahrenheit</button>
      <button onClick={() => handleConvert('celsius')}>Convert to Celsius</button>
    </div>
  );
};

export default TemperatureConverter;
```

Here's a React hook that allows you to convert between different temperature units:

```javascript
import React, { useState } from 'react';

const useTemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('C'); // Celsius (default)

  const handleInputChange = (event) => {
    setTemperature(parseFloat(event.target.value));
  };

  const handleUnitChange = (event) => {
    setUnit(event.target.value);
  };

  const convertToFahrenheit = () => {
    const convertedTemperature = (temperature * 1.8) + 32;
    return convertedTemperature.toFixed(2);
  };

  const convertToCelsius = () => {
    const convertedTemperature = (temperature - 32) / 1.8;
    return convertedTemperature.toFixed(2);
  };

  return {
    temperature,
    unit,
    handleInputChange,
    handleUnitChange,
    convertToFahrenheit,
    convertToCelsius,
  };
};

export default useTemperatureConverter;
```

This hook provides a state for the temperature value and the selected unit ('C' for Celsius or 'F' for Fahrenheit). It also includes functions to handle input changes, switch between units, and convert temperatures between Celsius and Fahrenheit.

