function calculateDiscount(purchaseAmount) {
  // Calculate the discount percentage based on the purchase amount
  const discountPercentage = (purchaseAmount >= 50) ? 10 : 5;

  // Apply the discount to the purchase amount
  const discountAmount = purchaseAmount * (discountPercentage / 100);

  // Check if the purchase amount meets the minimum requirement for the discount
  if (purchaseAmount >= 50) {
    // Apply the increased discount percentage for each $100 spent above the minimum purchase amount
    const additionalDiscountPercentage = (purchaseAmount - 50) / 100 * 5;
    const totalDiscountPercentage = discountPercentage + additionalDiscountPercentage;

    // Calculate the final discount amount
    const finalDiscountAmount = purchaseAmount * (totalDiscountPercentage / 100);

    return finalDiscountAmount;
  } else {
    return 0;
  }
}

