Here are three Python functions that use if statements, along with type hints and comments:

```python
# Define a function to check if a number is even or odd
def is_even(num: int) -> bool:
    """
    This function takes an integer as input and returns True if the number is even, False otherwise.
    """
    if num % 2 == 0:
        return True
    else:
        return False

# Define a function to calculate the factorial of a number
def factorial(num: int) -> int:
    """
    This function takes an integer as input and returns the factorial of the number.
    """
    if num == 0:
        return 1
    else:
        return num * factorial(num - 1)

# Define a function to check if a string is a palindrome
def is_palindrome(str: str) -> bool:
    """
    This function takes a string as input and returns True if the string is a palindrome, False otherwise.
    """
    for i in range(len(str) // 2):
        if str[i] != str[-i - 1]:
            return False
    return True
```

