async function openCameraAndMicrophone() {
  const devices = await navigator.mediaDevices.enumerateDevices();
  const cameraDevice = devices.find(device => device.kind === 'video');
  const microphoneDevice = devices.find(device => device.kind === 'audio');

  if (cameraDevice && microphoneDevice) {
    const stream = new MediaStream([cameraDevice.videoTrack, microphoneDevice.audioTrack]);
    return stream;
  }
}

