    Book catcherInTheRye("The Catcher in the Rye", "J.D. Salinger", "A coming-of-age story about a troubled teenager.");
    Book anotherBook("To Kill a Mockingbird", "Harper Lee", "A classic novel about racial injustice and moral courage.");
    Book yetAnotherBook("1984", "George Orwell", "A dystopian novel about a totalitarian society where individuality is suppressed.");

    // Check if any two books have the same title, author, and summary
    if (catcherInTheRye.isEqual(anotherBook)) {
        std::cout << "Catcher in the Rye and To Kill a Mockingbird have the same title, author, and summary." << std::endl;
