Here's a sample code snippet demonstrating how to create an email input field with auto-complete functionality using TypeScript, React, and the Downshift library:

```typescript
import { useCombobox } from 'downshift';
import axios from 'axios';

interface Email {
  email: string;
}

const EmailsAutocomplete = () => {
  const [emails, setEmails] = React.useState([]);
  const [query, setQuery] = React.useState('');

  const {
    isOpen,
    selectedItem,
    getMenuProps,
    getInputProps,
    getItemProps,
  } = useCombobox({
    items: emails,
    getItemValue: (item) => item.email,
  });

  const handleSearch = async (prefix: string) => {
    try {
      const response = await axios.get(`/api/emails?prefix=${prefix}`);
      setEmails(response.data);
    } catch (error) {
      console.error(error);
    }
  };

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setQuery(event.target.value);
    handleSearch(event.target.value);
  };

  const renderItem = ({ item }) => {
    return (
      <div {...getItemProps({ item })}>
        {item.email}
      </div>
    );
  };

  return (
    <div {...getMenuProps()}>
      <input
        {...getInputProps({
          placeholder: 'Search emails',
          value: query,
          onChange: handleInputChange,
        })}
      />
      {isOpen && (
        <ul {...getMenuProps()}>
          {emails.map(renderItem)}
        </ul>
      )}
    </div>
  );
};

export default EmailsAutocomplete;
```

Make sure to replace `/api/emails` with the actual API endpoint that fetches the emails based on the prefix.

