public class ProductCost {
    public static void main(String[] args) {
        int headphonesCount = 5;
        int microphonesCount = 2;
        int speakersCount = 3;

        double headphonesPrice = 50;
        double microphonesPrice = 100;
        double speakersPrice = 150;

