It seems like your issue is with the generation of the planets. You can try implementing a simple spatial partitioning algorithm to avoid placing two planets too close to each other. One common approach is the Quadtree data structure. Here's an example of how you can implement it in your code:

First, create a `Quadtree` class:
```javascript
class Quadtree {
  constructor(width, height, depth) {
    this.width = width;
    this.height = height;
    this.depth = depth;
    this.nodes = [];
  }

  insert(point) {
    if (this.nodes.length === 0) {
      this.nodes.push({
        point,
        children: [],
      });
    } else {
      this._insertHelper(point, 0, 0, this.nodes);
    }
  }

  _insertHelper(point, x, y, nodes) {
    const node = nodes[x];
    if (node.children.length === 4) {
      const newNode = {
        point,
        children: [],
      };
      node.children.push(newNode);
      this._insertHelper(point, x * 2, y * 2, node.children);
    } else {
      node.children.push(point);
    }
  }

  search(point) {
    return this._searchHelper(point, 0, 0, this.nodes);
  }

  _searchHelper(point, x, y, nodes) {
    if (nodes.length === 0) {
      return null;
    }
    const node = nodes[x];
    if (node.children.length === 4) {
      const result = this._searchHelper(point, x * 2, y * 2, node.children);
      if (result !== null) {
        return result;
      }
    }
    if (node.point.distanceToSquared(point) <= 9) {
      return node.point;
    }
    return this._searchHelper(point, x * 2, y * 2, node.children);
  }
}
```

